use pulldown_cmark::Options;
fn render(opts: Options, input: &str) -> String {
    let parser = pulldown_cmark::Parser::new_ext(input, opts);
    let mut html = String::new();
    pulldown_cmark::html::push_html(&mut html, parser);
    html
}
fn main() {
    let subscript_only = Options::ENABLE_SUBSCRIPT;
    let strike_only = Options::ENABLE_STRIKETHROUGH;
    let both = Options::ENABLE_SUBSCRIPT | Options::ENABLE_STRIKETHROUGH;

    let cases = [
        ("subscript_only", subscript_only, "~~This ~is~~ stricken.~"),
        ("subscript_only", subscript_only, "a ~[x](https://x)~"),
        ("subscript_only", subscript_only, "b ~~[x](https://x)~~"),
        ("subscript_only", subscript_only, "d ~~x ~[x](https://x)~ x~~"),
        ("strike_only", strike_only, "~~This is *stricken out*~~"),
        ("strike_only", strike_only, "~This is stricken out~"),
        ("strike_only", strike_only, "~This ~~is stricken.~~"),
        ("both", both, "~~This ~is~~ stricken.~"),
        ("both", both, "H~2~O"),
        ("both", both, "~~x ~y~ x~~"),
    ];
    for (label, opts, input) in cases {
        println!("[{label}] {:?} => {}", input, render(opts, input).trim());
    }
}
